const db=createClient(SUPABASE_URL,SUPABASE_KEY);
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,me=null,view=new URLSearchParams(location.search).has('chat')?'messages':'feed',feed=[],busy=false,toastTimer,loadId=0;
const revealed=new Set();
const postBodies=new Map();
let engagementReady=false;
const billing=createBilling({db,$,modal,esc,toast,getUser:()=>user,auth,refresh:load});
const community=createCommunity({getBilling:()=>billing,getBeta:()=>beta,db,$,esc,result,modal,close,toast,fail,guarded,requireProfile,getUser:()=>user,getMe:()=>me,getEnhancements:()=>enhancements,isEnhanced:()=>engagementReady,showProfile,card,bindCards,signed,avatar,recordView,isRevealed:id=>revealed.has(id),openFeed:(kind,series=null)=>{view=kind;selectedSeries=series;mainCatalog.reset();if(series)$('#series-filter').value=series.label;load();}});
const beta=createBetaTools({db,$,esc,result,modal,close,toast,guarded,fail,requireProfile,getUser:()=>user,moderation:(...args)=>community.moderation(...args),refresh:load});
const enhancements=createEnhancements({shareContent:id=>sharing.share(id),db,$,esc,result,modal,close,toast,fail,guarded,requireProfile,getUser:()=>user,getMe:()=>me,readMe,refresh:refreshCurrent,showProfile,openPost:id=>community.openPost(id),people:()=>community.people(),spoiler:p=>community.spoiler(p)});
if(new URLSearchParams(location.search).has('chat'))document.body.classList.add('chat-window');
const sharing=createSharing({db,result,esc,requireProfile,uid:()=>user?.id,fail,toast,openPost:id=>community.openPost(id),openStoryPost:async p=>{storyPosts=[...storyPosts.filter(s=>s.id!==p.id),p];storySequence=[p.id];await story(p.id);}});
const messages=createMessages({openShared:id=>sharing.open(id),separateWindow:!new URLSearchParams(location.search).has('chat'),db,$,esc,result,requireProfile,getUser:()=>user,avatar,showProfile,fail,getStories:async authors=>{if(!authors.length)return [];const rows=await result(db.from('posts').select('*,profiles!posts_author_fkey(*)').eq('kind','story').eq('status','approved').in('author',authors).gt('expires_at',new Date().toISOString()).order('created_at',{ascending:true}));storyPosts=[...new Map([...storyPosts,...rows].map(p=>[p.id,p])).values()];return rows;},storySeen:author=>storyGroupOpened(storyPosts,author,storyHistory()),openStory:async id=>{const p=storyPosts.find(p=>p.id===id);storySequence=storyPosts.filter(s=>s.author===p.author&&Date.parse(s.expires_at)>Date.now()).map(s=>s.id);await story(id);}});
const siteSearch=createSearch({db,esc,showProfile,openPost:id=>community.openPost(id),messagePerson:person=>messages.composeTo(person),getUser:()=>user});
const names={messages:'Messages',feed:'Home',explore:'Explore',theory:'Theories',episodes:'Episodes',chapters:'Chapters',profile:'Profile'};
let storyFollowing=new Set();
let storyPosts=[],activeProfile=null,profilePage=0,profilePosts=[];
const PAGE_SIZE=24;
let selectedSeries=null,feedPage=0,feedHasMore=false;
const catalogMedium=()=>view==='episodes'?'anime':view==='chapters'?'manga':null;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function modal(html,storyMode=false){if(!storyMode){stopStoryPlayback();storyEpoch++;storySequence=[];}$('#modal').classList.remove('story-editor-modal','comments-modal','viewers-open','compose-modal');$('#modal').classList.toggle('story-modal',storyMode);$('#modal-body').innerHTML=storyMode?'<div class="story-card">'+html+'</div>':html;$('#modal').scrollTop=0;if(!$('#modal').open)$('#modal').showModal();}
let storyAnimation=0,storyEpoch=0,storySequence=[];
function stopStoryPlayback(){cancelAnimationFrame(storyAnimation);storyAnimation=0;}
function close(){stopStoryPlayback();storyEpoch++;storySequence=[]; $('#modal').close();$('#modal').classList.remove('story-modal','viewers-open'); }
function fail(e){console.error(e);toast(e.message||'Something went wrong. Please try again.');}
async function result(promise){const r=await promise;if(r.error)throw r.error;return r.data;}
function guarded(fn){return async e=>{e?.preventDefault();if(busy)return;busy=true;const buttons=$('#modal-body').querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await fn(e);}catch(e){fail(e);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}};}
function requireProfile(){if(me?.account_suspended){toast('Your account is suspended. Contact the moderator from account settings.');return false;}if(!user){auth();return false;}if(!me){profileEditor();return false;}return billing.gate();}
async function readMe(){messages.badge().catch(console.error);if(!engagementReady){const ready=await db.rpc('engagement_ready');engagementReady=!ready.error&&ready.data===true;}me=user?await result(db.from('profiles').select('*').eq('id',user.id).maybeSingle()):null;$('#account').textContent=me?me.display_name:user?'Set up profile':'Sign in';$('.create-row p').textContent=user?'Share a post or add to your story.':'Browse freely. Sign in to join the conversation.';try{await community.refresh();if(engagementReady)await enhancements.loadPins();}catch(e){console.error(e);}paintRail().catch(console.error);}
async function signed(path){if(!path)return null;try{return (await result(db.storage.from('community-media').createSignedUrl(path,60))).signedUrl;}catch{return null;}}
async function avatar(p){const url=await signed(p?.avatar_path);return url?`<img class="avatar" alt="${esc(p.display_name)} profile picture" src="${esc(url)}">`:`<span class="avatar">${esc((p?.display_name||'?')[0].toUpperCase())}</span>`;}
function empty(title,body){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(body)}</p></div>`;}
const authorStoryCache=new Map();
async function authorStories(author,fresh=false){
 if(!user||!author)return [];
 const key=user.id+':'+author,cached=authorStoryCache.get(key);
 if(!fresh&&cached&&Date.now()-cached.at<30000)return cached.rows.filter(p=>Date.parse(p.expires_at)>Date.now());
 const rows=await result(db.from('posts').select('*,profiles!posts_author_fkey(*)').eq('author',author).eq('kind','story').eq('status','approved').gt('expires_at',new Date().toISOString()).order('created_at',{ascending:true}).order('id').limit(500));
 authorStoryCache.set(key,{at:Date.now(),rows});return rows;
}
async function storyAvatar(profile){
 const picture=await avatar(profile);let rows=[];
 try{rows=await authorStories(profile?.id);}catch{ /* Avatar remains usable if stories cannot be read. */ }
 if(!rows.length)return picture;
 const seen=storyGroupOpened(rows,profile.id,storyHistory());
 return `<button class="author-story-avatar ${seen?'seen-story':''}" data-author-story="${esc(profile.id)}" aria-label="Watch ${esc(profile.display_name)}’s story"><span class="story-ring">${picture}</span></button>`;
}
async function openAuthorStories(author){
 if(!requireProfile())return;
 const rows=await authorStories(author,true);
 if(!rows.length){toast('No active stories to view.');await refreshCurrent();return;}
 storyPosts=[...storyPosts.filter(p=>p.author!==author),...rows];
 storySequence=rows.map(p=>p.id);await story(storySequence[0]);
}
function bindStoryAvatars(root=document){root.querySelectorAll('[data-author-story]').forEach(b=>b.onclick=()=>openAuthorStories(b.dataset.authorStory).catch(fail));}
async function load(){siteSearch.sync(view);messages.stop();activeProfile=null;const request=++loadId;feedPage=0;feed=[];await billing.status();await billing.returned();if(billing.blocked()&&view!=='profile'){stopStoryPlayback();$('#story-strip').hidden=true;$('.create-row').hidden=true;$('.community-tools').hidden=true;$('#filters').hidden=true;$('#intro').hidden=true;$('#view-title').textContent='FictionCom';$('#content').innerHTML=billing.render();$('#feed-membership').onclick=()=>billing.open().catch(fail);return;}
 $('#story-strip').hidden=view!=='feed';$('.create-row').hidden=true;$('.community-tools').hidden=['messages','profile','feed','explore'].includes(view);if(view==='feed')renderStoryStrip(request);$('#view-title').textContent=names[view]||'FictionCom';$('#intro').hidden=view!=='theory';$('#filters').hidden=['profile','feed','messages','explore'].includes(view);$('main').classList.toggle('home-feed',view==='feed'||view==='explore');document.body.dataset.screen=view;document.querySelectorAll('button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));paintRail().catch(()=>{});
 if(selectedSeries&&catalogMedium()&&selectedSeries.medium!==catalogMedium()){selectedSeries=null;mainCatalog.reset();}
 $('#series-page').hidden=!selectedSeries;$('#series-filter').placeholder=view==='episodes'?'Search anime…':view==='chapters'?'Search manga…':'Search anime or manga…';
 $('#content').innerHTML=empty('Loading…','Finding the latest conversations.');
 if(view==='messages'){await messages.inbox();return;}
 if(view==='profile'){if(!user){$('#content').innerHTML='<section class="empty"><h2>Make yourself at home</h2><p>Create your profile, choose your favorite anime and manga, and connect with other fans. Browse freely; an account is required to post, react, follow or chat.</p><div class="form-actions"><button id="guest-create-profile" class="primary">Create account</button><button id="guest-profile-signin">Sign in</button></div></section>';$('#guest-create-profile').onclick=()=>auth('signup');$('#guest-profile-signin').onclick=()=>auth();return;}if(!me){profileEditor();$('#content').innerHTML=empty('Make yourself at home','Set up your profile to join the conversation.');return;}await showProfile(user.id,request);return;}
 await loadFeedPage(request,true);
}
async function exploreTile(p){const hidden=community.spoiler(p)&&!revealed.has(p.id);const url=!hidden&&p.media_path?await signed(p.media_path):null;return `<button type="button" class="explore-tile" data-open-explore="${p.id}" aria-label="Open post">${hidden?'<span class="tile-text">Spoiler</span>':url?(p.media_type==='video'?`<video muted playsinline preload="metadata" src="${esc(url)}"></video><span class="tile-kind">▶</span>`:`<img loading="lazy" src="${esc(url)}" alt="">`):`<span class="tile-text">${esc((p.title||p.body||'Post').slice(0,80))}</span>`}${hidden?'<span class="explore-spoiler">Spoiler</span>':''}</button>`;}
async function loadFeedPage(request,reset=false){try{
 if(view==='explore'){const posts=await result(db.from('posts').select('*,profiles!posts_author_fkey(*)').eq('status','approved').not('kind','in','(story,avatar)').order('created_at',{ascending:false}).order('id').range(feedPage*PAGE_SIZE,(feedPage+1)*PAGE_SIZE-1));if(request!==loadId)return;const tiles=await Promise.all(posts.map(exploreTile));if(request!==loadId)return;if(reset)$('#content').innerHTML='<div id="feed-posts" class="explore-grid"></div><button id="more-discussions" class="quiet load-more">Load more</button>';feed.push(...posts);feedPage++;feedHasMore=posts.length===PAGE_SIZE;$('#feed-posts').insertAdjacentHTML('beforeend',tiles.join(''));if(!feed.length)$('#feed-posts').innerHTML=empty('Nothing to explore yet','New photos and videos will show up here.');const more=$('#more-discussions');more.hidden=!feedHasMore;more.disabled=false;more.onclick=()=>{more.disabled=true;loadFeedPage(request);};document.querySelectorAll('[data-open-explore]').forEach(b=>b.onclick=()=>community.openPost(b.dataset.openExplore).catch(fail));return;}
 let q=db.from('posts').select('*,profiles!posts_author_fkey(*)').neq('kind','avatar');
 if(view==='feed')q=user||engagementReady?db.rpc('home_feed',{page_number:feedPage,limit_count:PAGE_SIZE}).select('*,profiles!posts_author_fkey(*)'):q.neq('kind','story').order('created_at',{ascending:false}).order('id').range(feedPage*PAGE_SIZE,(feedPage+1)*PAGE_SIZE-1);
 if(view==='theory')q=q.eq('kind','theory');else if(view==='episodes'||view==='chapters')q=q.eq('kind','reaction').eq('medium',catalogMedium());else q=q.neq('kind','story');
 if(view!=='feed'){if(user&&!selectedSeries&&!$('#series-filter').value.trim()&&$('#discussion-sort').value==='recommended')q=db.rpc('recommended_discussions',{tab:view,page_number:feedPage,limit_count:PAGE_SIZE}).select('*,profiles!posts_author_fkey(*)');const title=$('#series-filter').value.trim();if(selectedSeries)q=q.eq('series',selectedSeries.title).eq('medium',selectedSeries.medium);else if(title)q=q.ilike('series',title.replace(/[\%_]/g,'\$&'));
 const recommended=user&&!selectedSeries&&!title&&$('#discussion-sort').value==='recommended';const sort=$('#discussion-sort').value;if(!recommended){if(sort==='episode-asc'||sort==='episode-desc')q=q.order('episode',{ascending:sort==='episode-asc',nullsFirst:false}).order('created_at',{ascending:false});else q=q.order('created_at',{ascending:sort==='oldest'});q=q.order('id',{ascending:true}).range(feedPage*PAGE_SIZE,(feedPage+1)*PAGE_SIZE-1);}}
 const posts=await result(q);if(view==='feed'&&user){const follows=await result(db.from('follows').select('following').eq('follower',user.id).eq('accepted',true));const circle=new Set([user.id,...follows.map(f=>f.following)]);posts.forEach(p=>p.suggested=!circle.has(p.author));}if(request!==loadId)return;const cards=await Promise.all(posts.map(card));if(request!==loadId)return;
 if(reset)$('#content').innerHTML=`<div id="feed-posts"></div><button id="more-discussions" class="quiet load-more">${view==='feed'?'Load more posts':'Load more discussions'}</button>`;
 feed.push(...posts);feedPage++;feedHasMore=posts.length===PAGE_SIZE;$('#feed-posts').insertAdjacentHTML('beforeend',cards.join(''));if(!feed.length)$('#feed-posts').innerHTML=empty('No discussions yet',selectedSeries?'Be the first to post about '+selectedSeries.label+'.':'Choose a series or start a new conversation.');const more=$('#more-discussions');more.hidden=!feedHasMore;more.disabled=false;more.onclick=()=>{more.disabled=true;loadFeedPage(request);};bindCards();
 }catch(e){if(request!==loadId)return;if(reset)$('#content').innerHTML=empty('Couldn’t load discussions','Please refresh to try again.');else{toast('Couldn’t load more. Please try again.');$('#more-discussions').disabled=false;}console.error(e);}}
const igIcon={
 heart:'<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M12 20.2s-7.2-4.4-7.2-9.1A4.4 4.4 0 0 1 12 7.6a4.4 4.4 0 0 1 7.2 3.5c0 4.7-7.2 9.1-7.2 9.1Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
 comment:'<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M5 17.5 3.5 21l3.6-1.4A8.5 8.5 0 1 0 5 17.5Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
 share:'<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M21 4.5 3.8 11.2c-.9.4-.8 1.6.1 1.8l6.2 1.5 1.6 6.1c.3.9 1.5.9 1.8 0L21 4.5Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
 save:'<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M6 3.8h12a1 1 0 0 1 1 1V21l-7-4-7 4V4.8a1 1 0 0 1 1-1Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
 mute:'<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4Zm12.5 3a4 4 0 0 0-2-3.4M18 6l-3 3m3 6-3-3" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'
};
function relTime(date){const s=Math.max(0,(Date.now()-new Date(date).getTime())/1000);if(s<45)return 'Just now';if(s<3600)return Math.max(1,Math.floor(s/60))+'m';if(s<86400)return Math.floor(s/3600)+'h';if(s<604800)return Math.floor(s/86400)+'d';if(s<31536000)return Math.floor(s/604800)+'w';return Math.floor(s/31536000)+'y';}
function richCaption(text){const src=String(text),parts=[];const re=/(@[a-z0-9_]{3,24}|#[A-Za-z0-9_]{1,40})/gi;let last=0,m;while((m=re.exec(src))){parts.push(esc(src.slice(last,m.index)));const token=m[0],kind=token[0]==='#';parts.push(`<button type="button" class="${kind?'ig-hash':'ig-mention'}" data-${kind?'hashtag':'mention'}="${esc(token.slice(1).toLowerCase())}">${esc(token)}</button>`);last=m.index+token.length;}parts.push(esc(src.slice(last)));return parts.join('');}
async function card(p){
 postBodies.set(p.id,p.body||'');
 const author=p.profiles;
 const stats=await result(db.rpc('post_stats',{target:p.id}));
 const liked=user?await result(db.from('likes').select('user_id').eq('post_id',p.id).eq('user_id',user.id).maybeSingle()):null;
 const savedRow=user?await result(db.from('saved_posts').select('post_id').eq('post_id',p.id).eq('user_id',user.id).maybeSingle()):null;
 const isHidden=community.spoiler(p)&&!revealed.has(p.id);
 const slides=[];
 if(p.media_path&&!isHidden&&p.kind!=='story'){
  const url=await signed(p.media_path);
  if(url)slides.push(p.media_type==='video'?`<video class="media" src="${esc(url)}" muted playsinline loop preload="metadata" data-video="${p.id}"></video>`:`<img class="media" src="${esc(url)}" alt="Image shared by ${esc(author?.display_name)}" loading="lazy">`);
  const attachments=await result(db.from('post_media').select('*').eq('post_id',p.id).order('position'));
  for(const a of attachments){const extra=await signed(a.path);if(extra)slides.push(a.media_type==='video'?`<video class="media" src="${esc(extra)}" muted playsinline loop preload="metadata" data-video="${p.id}"></video>`:`<img class="media" src="${esc(extra)}" alt="Additional post image" loading="lazy">`);}
 }
 const count=slides.length;
 const media=count?`<div class="ig-media" data-slides="${count}"><div class="media-carousel">${slides.join('')}</div>${count>1?`<span class="ig-index">1/${count}</span><button type="button" class="ig-arrow prev" data-car="prev" aria-label="Previous photo" disabled>‹</button><button type="button" class="ig-arrow next" data-car="next" aria-label="Next photo">›</button>`:''}${slides.some(s=>s.includes('<video'))?`<button type="button" class="ig-mute" aria-label="Unmute">${igIcon.mute}</button>`:''}<div class="ig-burst" aria-hidden="true">♥</div></div>${count>1?`<div class="ig-dots">${slides.map((_,i)=>`<button type="button" class="ig-dot${i?'':' on'}" data-dot="${i}" aria-label="Photo ${i+1}"></button>`).join('')}</div>`:''}`:'';
 const seriesLabel=p.series?`${p.series}${p.kind==='reaction'&&p.episode?` · ${p.medium==='manga'?'Chapter':'Episode'} ${p.episode}`:''}`:'';
 const username=author?.username||author?.display_name||'member';
 const body=p.body||'';
 const short=body.length>125?body.slice(0,125).trimEnd()+'…':body;
 const subtitle=[seriesLabel,p.suggested?'Suggested for you':''].filter(Boolean).join(' · ');
 const menu=[
  engagementReady&&p.suggested?`<button type="button" data-dismiss="${p.id}">Not interested</button>`:'',
  engagementReady&&p.author===user?.id&&p.status==='approved'&&!['story','avatar'].includes(p.kind)?`<button type="button" data-pin="${p.id}">${enhancements.isPinned(p.id)?'Unpin':'Pin'}</button>`:'',
  p.author===user?.id&&p.media_path&&p.status==='pending'?`<button type="button" data-ai-review="${p.id}">Finish upload</button>`:'',
  p.author===user?.id&&!['story','avatar'].includes(p.kind)&&p.status==='approved'?`<button type="button" data-edit-post="${p.id}">Edit</button>`:'',
  p.author===user?.id?`<button type="button" data-delete="${p.id}">Delete</button>`:'',
  p.author===user?.id&&p.kind==='story'?`<button type="button" data-viewers="${p.id}">Viewers</button>`:'',
  p.author!==user?.id?`<button type="button" data-report="${p.id}">Report</button>`:''
 ].filter(Boolean).join('');
 const likes=stats.likes||0;
 return `<article class="post social-post" data-post="${p.id}"><div class="post-head">${await storyAvatar(author)}<div class="ig-id"><button type="button" data-person="${p.author}"><strong>${esc(username)}</strong></button>${subtitle?`<button type="button" class="text-button meta" data-series="${esc(p.series||'')}" data-medium="${esc(p.medium||'')}">${esc(subtitle)}</button>`:''}</div><details class="ig-menu"><summary aria-label="More options">•••</summary><div class="ig-menu-pop">${menu||'<button type="button" disabled>No other actions</button>'}</div></details></div>${p.status!=='approved'?`<p class="status">${p.status==='pending'?'Upload incomplete · only visible to you':'Upload removed · only visible to you'}</p>`:''}${isHidden?`<div class="spoiler ig-spoiler"><strong>Spoilers ahead</strong><p>${esc(seriesLabel||'This post')}</p><button type="button" data-reveal="${p.id}">See post</button></div>`:media}${p.kind==='story'?`<div class="post-body"><button type="button" data-story="${p.id}" class="primary">Watch story</button><p class="small">Expires ${new Date(p.expires_at).toLocaleString()}</p></div>`:''}<div class="actions ig-actions"><div class="ig-actions-left"><button type="button" data-like="${p.id}" class="ig-action${liked?' liked':''}" aria-label="${liked?'Unlike':'Like'} post">${igIcon.heart}</button><button type="button" data-comments="${p.id}" class="ig-action" aria-label="Comment">${igIcon.comment}</button><button type="button" data-share="${p.id}" class="ig-action" aria-label="Share post">${igIcon.share}</button></div><button type="button" data-save="${p.id}" class="ig-action${savedRow?' saved':''}" aria-label="${savedRow?'Remove from saved':'Save'}">${igIcon.save}</button></div><div class="ig-foot"><button type="button" class="ig-likes" data-like-total="${p.id}" ${likes?'':'hidden'}><strong>${likes} ${likes===1?'like':'likes'}</strong></button><div class="ig-caption"><button type="button" class="ig-author" data-person="${p.author}">${esc(username)}</button> <span class="post-copy" data-copy="${p.id}">${richCaption(short)}</span>${body.length>125?` <button type="button" class="ig-more" data-expand="${p.id}" aria-expanded="false">more</button>`:''}</div>${p.title?`<p class="small">${esc(p.title)}</p>`:''}${stats.comments?`<button type="button" class="ig-comments-link" data-comments="${p.id}">View all ${stats.comments} comments</button>`:`<button type="button" class="ig-comments-link" data-comments="${p.id}">Add a comment</button>`}<time class="ig-time">${relTime(p.created_at)}</time></div></article>`;
}
