  const pill=root.querySelector('.ig-index');
  const total=Number(root.dataset.slides)||1;
  const sync=()=>{const i=Math.max(0,Math.min(total-1,Math.round(scroller.scrollLeft/(scroller.clientWidth||1))));dotButtons.forEach((d,n)=>d.classList.toggle('on',n===i));if(pill)pill.textContent=(i+1)+'/'+total;const prev=root.querySelector('[data-car="prev"]'),next=root.querySelector('[data-car="next"]');if(prev)prev.disabled=i<=0;if(next)next.disabled=i>=total-1;};
