 const signup=mode==='signup';modal(`<h2>${signup?'Create your FictionCom account':'Welcome back'}</h2><p class="small">${signup?'FictionCom is free to use. No card or subscription is required. Create your account and set up your profile. Read the <a href="terms.html" target="_blank" rel="noopener">Terms</a> and <a href="privacy.html" target="_blank" rel="noopener">Privacy notice</a> first.':'Sign in to post, react, and follow your favorite creators.'}</p><form id="auth-form">${signup?'<label>Username<input id="signup-username" autocomplete="username" pattern="[a-z0-9_]{3,24}" minlength="3" maxlength="24" required placeholder="e.g. moonlit_manga"></label><p class="small">Use 3–24 lowercase letters, numbers, or underscores.</p><label>First name<input id="first-name" autocomplete="given-name" maxlength="60" required></label><label>Last name<input id="last-name" autocomplete="family-name" maxlength="60" required></label><p class="small">Your first and last name are stored with your account. Choose your public display name when setting up your profile.</p>':''}<label>Email<input id="email" type="email" autocomplete="email" required></label><label>Password<input id="password" type="password" ${signup?'minlength="10"':''} autocomplete="${signup?'new-password':'current-password'}" required></label>${signup?'<label>Confirm password<input id="confirm-password" type="password" autocomplete="new-password" required></label><label class="check"><input id="accept-rules" type="checkbox" required> I am at least 14 years old and agree to the community rules, Terms and Privacy notice. No nudity, explicit content, harassment, or stolen work.</label>':''}<p id="auth-error" class="error" role="alert"></p><button class="primary auth-submit">${signup?'Create account':'Sign in'}</button><p class="small">${signup?'Already have an account?':'New to FictionCom?'} <button id="auth-switch" type="button" class="text-button">${signup?'Sign in':'Create account'}</button></p>${signup?'':'<button type="button" id="reset" class="quiet">Forgot password?</button>'}</form>`);
 const oauth=provider=>guarded(async()=>{await result(db.auth.signInWithOAuth({provider,options:{redirectTo:location.origin+location.pathname}}));});if($('#google')){$('#google').onclick=oauth('google');$('#google').disabled=!OAUTH_READY.google;if(!OAUTH_READY.google)$('#google').textContent='Google sign-in · coming soon';}$('#auth-switch').onclick=()=>auth(signup?'signin':'signup');
 $('#auth-form').onsubmit=guarded(async()=>{const email=$('#email').value.trim().toLowerCase(),password=$('#password').value;$('#auth-error').textContent='';try{if(signup){const username=$('#signup-username').value.trim().toLowerCase(),firstName=$('#first-name').value.trim(),lastName=$('#last-name').value.trim();if(!/^[a-z0-9_]{3,24}$/.test(username))throw Error('Choose a username with 3–24 lowercase letters, numbers, or underscores.');if(!firstName||!lastName)throw Error('Enter your first and last name.');if(password!==$('#confirm-password').value)throw Error('Your passwords do not match.');const existing=await result(db.from('profiles').select('id').eq('username',username).limit(1));if(existing.length)throw Error('That username is already taken. Choose another username.');const data=await result(db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname,data:{age_14_or_older:true,username,first_name:firstName,last_name:lastName}}}));if(Array.isArray(data.user?.identities)&&data.user.identities.length===0)throw Error('This email is already linked to an account. Sign in instead, or use Forgot password to recover access.');if(data.session){close();toast('Account registered. Welcome to FictionCom.');}else{modal('<h2>Check your email</h2><p>Your registration request is received. Verify your email using the confirmation link, then sign in to set up your profile.</p><p>FictionCom is free. No card or subscription is required.</p><button id="back-signin" class="primary">Back to sign in</button>');$('#back-signin').onclick=()=>auth();}}else{await result(db.auth.signInWithPassword({email,password}));close();toast('Welcome back.');}}catch(e){$('#auth-error').textContent=signup&&(['user_already_exists','email_exists'].includes(e.code)||/already (?:registered|exists)/i.test(e.message||''))?'This email is already linked to an account. Sign in instead, or use Forgot password to recover access.':e.message||'Unable to sign in. Please try again.';}});
 if(!signup)$('#reset').onclick=()=>requestPasswordReset($('#email').value.trim());
