async function loadSavedGrid(){const node=$('#profile-panel-saved');if(!node||!user)return;const rows=await result(db.from('saved_posts').select('post_id,posts(id,title,body,series,media_path,media_type,spoiler)').eq('user_id',user.id).order('created_at',{ascending:false}).limit(60));node.innerHTML=rows.length?'<div class="profile-grid">'+(await Promise.all(rows.map(async r=>{const p=r.posts;if(!p)return '';const url=p.media_path&&!p.spoiler?await signed(p.media_path):null;return '<button type="button" class="profile-thumbnail" data-saved-open="'+p.id+'">'+(url?'<img src="'+esc(url)+'" alt="">':'<span class="tile-text">'+esc(p.title||p.series||(p.body||'').slice(0,80)||'Saved')+'</span>')+'</button>';}))).join('')+'</div>':empty('Nothing saved yet','Tap the bookmark on a post to find it here.');node.querySelectorAll('[data-saved-open]').forEach(b=>b.onclick=()=>community.openPost(b.dataset.savedOpen).catch(fail));}
