 modal(`<div class="compose-tabs" role="tablist"><button type="button" id="compose-tab-photo" aria-selected="${kind!=='theory'}">Photo / Video</button><button type="button" id="compose-tab-theory" aria-selected="${kind==='theory'}">Theory / Text</button></div><h2>${kind==='theory'?'New theory':reaction?'Share '+(medium==='anime'?'an episode':'a chapter')+' reaction':'Create new post'}</h2><form id="post-form"><label>Post type<input value="${kind==='theory'?'Theory':reaction?(medium==='anime'?'Episode reaction':'Chapter reaction'):'Post'}" readonly></label><label>Title<input id="title" maxlength="120"></label><label>Your post<textarea id="body" maxlength="5000" required placeholder="Share your thoughts…"></textarea></label><a id="large-editor" class="text-button" target="_blank">Open writing editor in a new tab</a><label>${reaction?(medium==='anime'?'Anime':'Manga'):'Anime or manga'}<input id="series" maxlength="100" placeholder="Choose a series" ${kind!=='post'?'required':''}></label>${reaction?`<label>${medium==='anime'?'Episode':'Chapter'}<input id="episode" type="number" min="1" max="100000" required></label>`:''}<label class="check"><input id="spoiler" type="checkbox"> Contains spoilers</label><div class="media-picker"><span>Photos or short videos</span><input id="media" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" hidden><input id="post-camera-photo" type="file" accept="image/*" capture="environment" hidden><input id="post-camera-video" type="file" accept="video/*" capture="environment" hidden><button id="add-post-media" type="button" class="media-picker-button"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/></svg><span>Add photos or videos</span><span class="media-picker-plus" aria-hidden="true">＋</span></button></div><div class="capture-actions"><button type="button" id="take-post-photo">Take photo</button><button type="button" id="take-post-video">Record video</button></div><div id="attachment-order" class="attachment-order"></div><p id="draft-status" class="small" role="status">Drafts save on this device.</p><button type="button" id="discard-draft" class="text-button">Discard draft</button><div id="upload-status" hidden><progress id="upload-progress" max="100" value="0"></progress><span id="upload-label" role="status"></span></div><p class="small">Up to 6 attachments, 10 MB each. Videos up to 5 minutes. Camera capture is available on supported devices. No nudity or inappropriate content.</p><label class="check"><input type="checkbox" required> My content follows the community rules.</label><button class="primary">Post</button></form>`);
 $('#modal').classList.add('compose-modal');$('#compose-tab-photo').onclick=()=>{if(kind!=='post')compose('post');};$('#compose-tab-theory').onclick=()=>{if(kind!=='theory')compose('theory');};const form=$('#post-form'),field=id=>form.querySelector('#'+id),owner=user.id,draftKey=owner+':'+context;let postSeries=null,files=[],published=false,timer,writeQueue=Promise.resolve(),previewUrls=[];
 configureCaptureButtons(field('take-post-photo'),field('take-post-video'),field('post-camera-photo'),field('post-camera-video'));
 field('take-post-photo').onclick=()=>field('post-camera-photo').click();field('take-post-video').onclick=()=>field('post-camera-video').click();
 field('add-post-media').onclick=()=>field('media').click();
 const status=message=>{if(form.isConnected)field('draft-status').textContent=message;};
 const snapshot=()=>({title:field('title').value,body:field('body').value,series:field('series').value,selected:postSeries,episode:field('episode')?.value||'',spoiler:field('spoiler').checked,files:files.map(f=>({name:f.name,lastModified:f.lastModified,blob:f}))});
 const persist=()=>{if(published)return writeQueue;const data=snapshot();writeQueue=writeQueue.catch(()=>{}).then(()=>saveDraft(draftKey,data)).then(()=>status('Draft saved on this device.'),()=>status('Device storage is unavailable. Keep this window open to retain your draft.'));return writeQueue;};
