 function attachments(){previewUrls.forEach(URL.revokeObjectURL);previewUrls=[];field('attachment-order').innerHTML=files.map((f,i)=>{const url=URL.createObjectURL(f);previewUrls.push(url);return `<div class="attachment-item">${f.type.startsWith('image/')?`<img src="${esc(url)}" alt="Attachment ${i+1}">`:'<span>Video</span>'}<span>${i+1}. ${esc(f.name)}</span><button type="button" data-move-attachment="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move attachment ${i+1} earlier">↑</button><button type="button" data-move-attachment="${i}" data-direction="1" ${i===files.length-1?'disabled':''} aria-label="Move attachment ${i+1} later">↓</button><button type="button" data-remove-attachment="${i}" aria-label="Remove attachment ${i+1}">×</button></div>`;}).join('');field('attachment-order').querySelectorAll('[data-move-attachment]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.moveAttachment),j=i+Number(b.dataset.direction);[files[i],files[j]]=[files[j],files[i]];attachments();schedule();});field('attachment-order').querySelectorAll('[data-remove-attachment]').forEach(b=>b.onclick=()=>{files.splice(Number(b.dataset.removeAttachment),1);attachments();schedule();});}
