r('keydown',e=>{if(e.key!=='Escape')return;const root=$('#notif-root');if(root&&!root.hidden&&!$('#modal').open){root.hidden=true;document.body.classList.remove('notif-open');}if($('#lightbox')&&!$('#lightbox').hidden){$('#lightbox').hidden=true;}});if($('#lightbox-close'))$('#lightbox-close').onclick=()=>{$('#lightbox').hidden=true;$('#lightbox-img').src='';};if($('#lightbox'))$('#lightbox').addEventListener('click',e=>{if(e.target.id==='lightbox'){$('#lightbox').hidden=true;$('#lightbox-img').src='';}});if($('#rail-see-all'))$('#rail-see-all').onclick=()=>(engagementReady?enhancements.discover():community.people()).catch(fail);
