async function uploadMediaPost(files,post,onProgress=()=>{}){
 for(const file of files)await validateMedia(file,300);
 if(['story','avatar'].includes(post.kind)&&files.length>1)throw Error('Stories and profile pictures use one attachment.');if(files.length>6)throw Error('Choose up to 6 attachments.');
 const types={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','video/mp4':'mp4','video/webm':'webm'};
 for(const f of files)if(!types[f.type]||f.size>10485760)throw Error('Each attachment must be JPG, PNG, WebP, MP4, or WebM and under 10 MB.');
 const paths=[],attempted=[];let inserted=null,uploadedBytes=0;const totalBytes=files.reduce((n,f)=>n+f.size,0)||1;
 try{for(let i=0;i<files.length;i++){const f=files[i],path=user.id+'/'+crypto.randomUUID()+'.'+types[f.type];toast('Uploading attachment '+(i+1)+' of '+files.length+'…');attempted.push(path);await uploadWithProgress({db,url:SUPABASE_URL,key:SUPABASE_KEY,path,file:f,onProgress:fraction=>onProgress((uploadedBytes+fraction*f.size)/totalBytes)});uploadedBytes+=f.size;paths.push({path,media_type:f.type.startsWith('image/')?'image':'video'});}
 inserted=await result(db.from('posts').insert({...post,ai_review_consent:false,media_path:paths[0].path,media_type:paths[0].media_type}).select('id').single());
 if(paths.length>1)await result(db.from('post_media').insert(paths.slice(1).map((p,i)=>({...p,post_id:inserted.id,position:i+1}))));await result(db.rpc('publish_upload',{target:inserted.id}));
 }catch(e){if(inserted)await db.from('posts').delete().eq('id',inserted.id).eq('author',user.id);if(attempted.length)await db.storage.from('community-media').remove(attempted);throw e;}
}


